    const BindingFlags Any=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
    static Type Runtime(string name)=>Type.GetType(name+", Assembly-CSharp",true);
    static object Get(object o,string n)=>o.GetType().GetField(n,Any) is FieldInfo f?f.GetValue(o):o.GetType().GetProperty(n,Any).GetValue(o);
    static object Call(object o,string n,params object[] a)=>o.GetType().GetMethods(Any).Single(m=>m.Name==n&&m.GetParameters().Length==a.Length).Invoke(o,a);
    static void Progress(string step,Fixture fixture=null){string folder=Path.GetFullPath("Logs/TruckSports/PlaytestRepair/Impossible07Goose");Directory.CreateDirectory(folder);string run=fixture!=null?fixture.run:"unbound";string state=fixture!=null&&fixture.match!=null?" running="+Get(fixture.match,"Running")+" paused="+Get(fixture.match,"Paused")+" phase="+(Get(fixture.match,"Rules") is LWS.TruckTruckGoose.GooseRules rules?rules.Phase.ToString():"null"):" unbound";string line=DateTime.UtcNow.ToString("O")+" | "+TestContext.CurrentContext.Test.Name+" | "+run+" | frame="+Time.frameCount+" realtime="+Time.realtimeSinceStartup.ToString("F3",System.Globalization.CultureInfo.InvariantCulture)+" scale="+Time.timeScale.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+" | "+step+state;using(var stream=new FileStream(Path.Combine(folder,"progress-V2.log"),FileMode.Append,FileAccess.Write,FileShare.ReadWrite)){using(var writer=new StreamWriter(stream,System.Text.Encoding.UTF8,1024,true)){writer.WriteLine(line);writer.Flush();}stream.Flush(true);}Debug.Log("GOOSE_NATIVE_V2 "+line);}
    sealed class Fixture:IDisposable
    {
        readonly IDisposable prefs;readonly InputSettings originalSettings,temporarySettings;readonly GameObject isolate;public Behaviour match;public readonly string run=Guid.NewGuid().ToString("N");
        public Fixture(){prefs=(IDisposable)Runtime("LWS.TruckSports.SportsPrefs").GetMethod("IsolateValidation").Invoke(null,new object[]{"Goose07Native"});originalSettings=InputSystem.settings;temporarySettings=UnityEngine.Object.Instantiate(originalSettings);temporarySettings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;temporarySettings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;InputSystem.settings=temporarySettings;isolate=new GameObject("Goose original input isolation");UnityEngine.Object.DontDestroyOnLoad(isolate);isolate.AddComponent(Runtime("LWS.TruckSports.SportsProbeInputIsolation"));}
        public IEnumerator Load(){Progress("Load.before-file-check",this);Assert.That(File.Exists("Assets/TruckTruckGoose/Scenes/TruckTruckGoose.unity"),Is.True,"Run the explicit NEW scene author first.");Progress("Load.before-scene-load",this);EditorSceneManager.LoadSceneInPlayMode("Assets/TruckTruckGoose/Scenes/TruckTruckGoose.unity",new LoadSceneParameters(LoadSceneMode.Single));Progress("Load.after-scene-load.before-yield1",this);yield return null;Progress("Load.after-yield1.before-yield2",this);yield return null;Progress("Load.after-yield2.before-match-bind",this);match=UnityEngine.Object.FindObjectsByType(Runtime("LWS.TruckTruckGoose.GooseMatch")).Cast<Behaviour>().Single();Progress("Load.after-match-bind.before-option",this);match.GetType().GetField("option",Any).SetValue(match,0);Progress("Load.before-AllBots",this);Call(match,"AllBots");Progress("Load.after-AllBots.before-StartMatch",this);Assert.That((bool)Call(match,"StartMatch"),Is.True);Progress("Load.after-StartMatch.before-yield3",this);yield return null;Progress("Load.after-yield3.done",this);}

        public void Dispose(){Progress("Dispose.begin",this);Time.timeScale=1;if(match!=null){Progress("Dispose.before-SetupScreen",this);Call(match,"SetupScreen");Progress("Dispose.after-SetupScreen",this);}Progress("Dispose.before-isolation-destroy",this);UnityEngine.Object.DestroyImmediate(isolate);Progress("Dispose.after-isolation-destroy.before-prefs",this);InputSystem.settings=originalSettings;UnityEngine.Object.DestroyImmediate(temporarySettings);prefs.Dispose();Progress("Dispose.complete",this);}
