    static void KeyboardOwners(object match,int humans,int total){var setup=Get(match,"setup");setup.GetType().GetField("count").SetValue(setup,total);var players=(Array)Get(setup,"players");Key[] forwards={Key.W,Key.UpArrow,Key.I,Key.T},lefts={Key.A,Key.LeftArrow,Key.J,Key.F},backs={Key.S,Key.DownArrow,Key.K,Key.G},rights={Key.D,Key.RightArrow,Key.L,Key.H};for(int i=0;i<total;i++){var p=players.GetValue(i);var source=p.GetType().GetField("source");source.SetValue(p,Enum.Parse(source.FieldType,i<humans?"Keyboard":"AI"));if(i<humans){p.GetType().GetField("forward").SetValue(p,forwards[i]);p.GetType().GetField("left").SetValue(p,lefts[i]);p.GetType().GetField("back").SetValue(p,backs[i]);p.GetType().GetField("right").SetValue(p,rights[i]);}}match.GetType().GetField("actionKeys").SetValue(match,new[]{Key.Space,Key.RightShift,Key.R,Key.U,Key.B,Key.Numpad0,Key.Digit0,Key.PageUp,Key.Space,Key.RightShift,Key.R,Key.U});}
    static void Keys(Keyboard keyboard,params Key[] keys){Progress("Keys.before-QueueStateEvent "+string.Join(",",keys));InputSystem.QueueStateEvent(keyboard,new KeyboardState(keys));Progress("Keys.after-QueueStateEvent.before-InputSystem.Update");InputSystem.Update();Progress("Keys.after-InputSystem.Update");}
    static void Capture(Fixture fixture,string name){string folder=Path.GetFullPath("Logs/TruckSports/PlaytestRepair/Impossible07Goose");Directory.CreateDirectory(folder);var canvas=((Component)Get(fixture.match,"menus")).GetComponent<Canvas>();var cameras=(Camera[])Get(fixture.match,"cameras");var save=Runtime("LWS.TruckSports.SportsControlledCapture").GetMethods().Single(m=>m.Name=="Save"&&m.GetParameters().Length==6);foreach(int width in new[]{1280,1920})save.Invoke(null,new object[]{canvas,cameras,width,width==1280?720:1080,Path.Combine(folder,name+"-"+width+"-controlled.png"),null});}
    [UnityTest,Timeout(360000)]public IEnumerator NaturalFullNwhAiCompletesThreeRoundsWithOppositeLegalClaims()
    {
        using(var f=new Fixture()){yield return f.Load();var rules=(LWS.TruckTruckGoose.GooseRules)Get(f.match,"Rules");var trucks=((Array)Get(f.match,"trucks")).Cast<Component>().ToArray();int count=rules.Scores.Length;Assert.That(count,Is.InRange(8,12));Assert.That(trucks.Take(count).All(t=>Get(t,"tractorMotor")!=null),Is.True);var start=trucks.Select(t=>t.transform.position).ToArray();float deadline=Time.realtimeSinceStartup+280;bool racing=false,captured=false,cameraChecked=false;double pickerProgress=0,gooseProgress=0;float nextProgress=Time.realtimeSinceStartup;while(!(bool)Get(f.match,"Finished")&&Time.realtimeSinceStartup<deadline){if(Time.realtimeSinceStartup>=nextProgress){Progress("Natural.tick round="+rules.Round+" scores="+string.Join(",",rules.Scores)+" picker="+rules.Picker+" goose="+rules.Goose,f);nextProgress=Time.realtimeSinceStartup+15;}if(!captured&&rules.Scores.Sum()==1){Progress("Natural.before-first-claim-Capture",f);Capture(f,"natural-first-legal-claim");Progress("Natural.after-first-claim-Capture",f);captured=true;}if(rules.Phase==LWS.TruckTruckGoose.GooseRules.Stage.Racing){racing=true;if(!cameraChecked){var action=Activator.CreateInstance(Runtime("LWS.TruckSports.SportsBroadcastAction"));Call(f.match,"DescribeBroadcast",action,null);Assert.That((int)Get(action,"primary"),Is.EqualTo(rules.Picker));Assert.That((bool)Get(action,"hasObjective"),Is.True);for(int slot=0;slot<count;slot++)Assert.That((bool)Call(f.match,"BroadcastParticipantActive",slot),Is.EqualTo(slot==rules.Picker||slot==rules.Goose));cameraChecked=true;}pickerProgress=Math.Max(pickerProgress,rules.Progress(rules.Picker));gooseProgress=Math.Max(gooseProgress,rules.Progress(rules.Goose));}yield return null;}Progress("Natural.loop-ended.before-assertions",f);TestContext.WriteLine("GOOSE_NATURAL count="+count+" racing="+racing+" progress="+pickerProgress+"/"+gooseProgress+" scores="+string.Join(",",rules.Scores)+" recoveries="+Get(f.match,"RecoveryCount"));Assert.That(racing,Is.True);Assert.That((bool)Get(f.match,"Finished"),Is.True);Assert.That(rules.Scores.Sum(),Is.EqualTo(3));Assert.That(Math.Max(pickerProgress,gooseProgress),Is.GreaterThanOrEqualTo(340));Assert.That(trucks.Select((t,i)=>Vector3.Distance(t.transform.position,start[i])).Max(),Is.GreaterThan(20));int receipts=(int)Get(Get(f.match,"ScoreJournal"),"Count");Assert.That(receipts,Is.EqualTo(3));}
    }
    [UnityTest,Timeout(60000)]public IEnumerator PauseAndRematchPreserveThenResetActualPhysicalStateAndRound()
    {
        using(var f=new Fixture()){yield return f.Load();yield return new WaitForSeconds(2);var rules=(LWS.TruckTruckGoose.GooseRules)Get(f.match,"Rules");var truck=((Array)Get(f.match,"trucks")).GetValue(rules.Picker);var body=(Rigidbody)Get(truck,"body");Call(f.match,"Pause",0,false);yield return null;Vector3 p=body.position;float clock=(float)Get(f.match,"RoundTime");yield return new WaitForSecondsRealtime(.2f);Assert.That(body.position,Is.EqualTo(p));Assert.That((float)Get(f.match,"RoundTime"),Is.EqualTo(clock));Call(f.match,"Resume");yield return new WaitForSeconds(.3f);Assert.That((float)Get(f.match,"RoundTime"),Is.GreaterThan(clock));Call(f.match,"SetupScreen");Call(f.match,"AllBots");Assert.That((bool)Call(f.match,"StartMatch"),Is.True);rules=(LWS.TruckTruckGoose.GooseRules)Get(f.match,"Rules");Assert.That(rules.Round,Is.EqualTo(1));Assert.That(rules.Scores.Sum(),Is.Zero);Assert.That((int)Get(Get(f.match,"ScoreJournal"),"Count"),Is.Zero);}
    }
    [UnityTest,Timeout(90000)]public IEnumerator OneThroughFourAssignedOwnersKeepOriginalNwhBodiesAndSplitViewOwnership()
    {
        using(var f=new Fixture()){
            Progress("Owners.before-Load",f);yield return f.Load();Progress("Owners.after-Load.before-AddKeyboard",f);var keyboard=InputSystem.AddDevice<Keyboard>();InputSystem.EnableDevice(keyboard);keyboard.MakeCurrent();Progress("Owners.after-AddKeyboard",f);
            try{
                var trucks=((Array)Get(f.match,"trucks")).Cast<Component>().ToArray();var bodies=trucks.Select(t=>(Rigidbody)Get(t,"body")).ToArray();
                for(int humans=1;humans<=4;humans++){
                    Progress("Owners.humans="+humans+".before-Keys-neutral",f);Keys(keyboard);Progress("Owners.humans="+humans+".after-Keys.before-SetupScreen",f);Call(f.match,"SetupScreen");Progress("Owners.humans="+humans+".after-SetupScreen.before-KeyboardOwners",f);KeyboardOwners(f.match,humans,8);Progress("Owners.humans="+humans+".after-KeyboardOwners.before-StartMatch",f);Assert.That((bool)Call(f.match,"StartMatch"),Is.True);Progress("Owners.humans="+humans+".after-StartMatch.before-get-views",f);var views=Get(f.match,"drivingViews");Progress("Owners.humans="+humans+".before-views.Select",f);Call(views,"Select",1);Progress("Owners.humans="+humans+".after-views.Select.before-yield1",f);yield return null;Progress("Owners.humans="+humans+".after-yield1.before-yield2",f);yield return null;Progress("Owners.humans="+humans+".after-yield2.before-assertions",f);
                    var rally=Get(views,"rally");Assert.That((int)Get(rally,"Humans"),Is.EqualTo(humans));CollectionAssert.AreEqual(Enumerable.Range(0,humans).ToArray(),((int[])Get(rally,"owners")).Take(humans).ToArray());for(int i=0;i<bodies.Length;i++)Assert.That(Get(trucks[i],"body"),Is.SameAs(bodies[i]));Progress("Owners.humans="+humans+".ownership-assertions-PASS",f);
                    if(humans==4){Vector3 start=bodies[0].position;Progress("Owners.before-Keys-W",f);Keys(keyboard,Key.W);Progress("Owners.after-Keys-W.before-WaitForSeconds2",f);float targetClock=(float)Get(f.match,"RoundTime")+2,waitDeadline=Time.realtimeSinceStartup+6;while((float)Get(f.match,"RoundTime")<targetClock&&Time.realtimeSinceStartup<waitDeadline)yield return null;Progress("Owners.after-bounded-simulation-wait.before-physical-assertions",f);Assert.That((float)Get(f.match,"RoundTime"),Is.GreaterThanOrEqualTo(targetClock),"Two genuine simulation seconds must complete; an input/focus pause must fail with telemetry rather than stall a scaled wait.");Assert.That(((Vector2[])Get(f.match,"commands"))[0].y,Is.GreaterThan(.9f));Assert.That(Vector3.Distance(bodies[0].position,start),Is.GreaterThan(.1f),"Assigned input must move the original NWH tractor physically.");Assert.That(((LWS.TruckTruckGoose.GooseRules)Get(f.match,"Rules")).Phase,Is.EqualTo(LWS.TruckTruckGoose.GooseRules.Stage.Picking));Progress("Owners.before-Capture",f);Capture(f,"four-owner-real-nwh-input");Progress("Owners.after-Capture",f);}
                }
            }finally{Progress("Owners.before-RemoveKeyboard",f);InputSystem.RemoveDevice(keyboard);Progress("Owners.after-RemoveKeyboard",f);}
        }
    }
